--
-- Name: enforce_photo_cap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_photo_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare is_prem boolean;
begin
  if new.image_keys is null or cardinality(new.image_keys) <= 1 then
    return new;
  end if;
  select coalesce(premium,false) into is_prem from profiles where id = new.user_id;
  if not coalesce(is_prem,false) then
    new.image_keys := new.image_keys[1:1];
  end if;
  return new;
end $$;

--
-- Name: follows_backfill_mutual(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.follows_backfill_mutual() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  alter table follows disable trigger user;

  insert into follows (follower_id, followee_id, status, created_at)
  select f.followee_id, f.follower_id, 'accepted', now()
    from follows f
   where f.status = 'accepted'
     and f.follower_id <> f.followee_id
  on conflict (follower_id, followee_id) do nothing;

  update follows g
     set status = 'accepted'
   where g.status is distinct from 'accepted'
     and exists (
       select 1 from follows f
        where f.follower_id = g.followee_id
          and f.followee_id = g.follower_id
          and f.status = 'accepted');

  alter table follows enable trigger user;
exception when others then
  -- Never leave the table with its triggers off.
  alter table follows enable trigger user;
  raise;
end $$;

--
-- Name: follows_reciprocate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.follows_reciprocate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.status is distinct from 'accepted' and new.status = 'accepted' then
    -- Tell notify_on_follow() to stay quiet: the person who asked has
    -- just been told "accepted your follow request", and "started
    -- following you" about the very same handshake is the same news
    -- twice. Transaction-local, and cleared as soon as the insert's
    -- AFTER triggers have run.
    perform set_config('crema.reciprocal','on',true);

    insert into follows (follower_id, followee_id, status)
    values (new.followee_id, new.follower_id, 'accepted')
    on conflict (follower_id, followee_id) do update
      set status = 'accepted'
      -- The WHERE is what ends the recursion: this UPDATE fires this
      -- same trigger again, and on the second pass the other side is
      -- already accepted, so no row changes and no trigger fires.
      where follows.status is distinct from 'accepted';

    perform set_config('crema.reciprocal','',true);
  end if;
  return new;
end $$;

--
-- Name: gear_fav(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gear_fav(p_kind text, p_name text, p_on boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if auth.uid() is null or btrim(coalesce(p_name,'')) = '' then return; end if;
  insert into user_gear (user_id, kind, name, fav_at)
  values (auth.uid(), p_kind, btrim(p_name), case when p_on then now() else null end)
  on conflict (user_id, kind, name)
    do update set fav_at = case when p_on then coalesce(user_gear.fav_at, now()) else null end;

  delete from user_gear
   where user_id = auth.uid() and kind = p_kind and name = btrim(p_name)
     and info is null and fav_at is null and not own;
end $$;

--
-- Name: gear_note(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gear_note(p_kind text, p_name text, p_info jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if auth.uid() is null or btrim(coalesce(p_name,'')) = '' then return; end if;
  insert into user_gear (user_id, kind, name, info)
  values (auth.uid(), p_kind, btrim(p_name), p_info)
  on conflict (user_id, kind, name) do update set info = excluded.info;

  delete from user_gear
   where user_id = auth.uid() and kind = p_kind and name = btrim(p_name)
     and info is null and fav_at is null and not own;
end $$;

--
-- Name: gear_remember(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gear_remember(p_kind text, p_name text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if auth.uid() is null or btrim(coalesce(p_name,'')) = '' then return; end if;
  insert into user_gear (user_id, kind, name, own)
  values (auth.uid(), p_kind, btrim(p_name), true)
  on conflict (user_id, kind, name) do update set own = true;
end $$;

--
-- Name: generate_challenges(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_challenges(at timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  wk_start timestamptz := date_trunc('week', at);           -- Postgres weeks start Monday
  wk_end   timestamptz := date_trunc('week', at) + interval '7 days';
  wk_num   int := floor(extract(epoch from date_trunc('week', at)) / 604800)::int;
  cats     text[] := array['habit','craft','discovery'];
  offs     int[]  := array[0, 2, 5];                        -- so the trio varies, not just each list
  made     int := 0;
  i        int;
  t        record;
  cid      text;
begin
  for i in 1 .. array_length(cats, 1) loop
    -- Explicit columns, not `select *`: the ranking subquery carries two
    -- window columns of its own, and a %rowtype target would choke on
    -- the extra attributes.
    select ranked.kind, ranked.goal, ranked.param, ranked.title, ranked.blurb,
           ranked.tag, ranked.pattern, ranked.points
      into t
      from (
      select tt.*, row_number() over (order by tt.code) - 1 as ix,
             count(*) over () as total
        from challenge_templates tt
       where tt.cat = cats[i] and tt.active
    ) ranked
     where ranked.ix = (wk_num + offs[i]) % ranked.total;

    continue when not found;

    cid := 'w' || to_char(wk_start, 'IYYY-IW') || '-' || cats[i];

    insert into challenges (id, title, tag, pattern, blurb, sort,
                            kind, goal, param, points, cat, starts_at, ends_at, ends, participants)
    values (cid, t.title, t.tag, t.pattern, t.blurb, i,
            t.kind, t.goal, t.param, t.points, cats[i], wk_start, wk_end, '7d', 0)
    on conflict (id) do update set
      -- Re-running mid-week must not move the goalposts under someone who
      -- is halfway through, so the rule itself is left alone; only the
      -- copy is refreshed.
      title = excluded.title, blurb = excluded.blurb, tag = excluded.tag,
      pattern = excluded.pattern, sort = excluded.sort;

    made := made + 1;
  end loop;
  return made;
end $$;

--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin(uid uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select p.is_admin from profiles p where p.id = uid), false);
$$;

--
-- Name: is_suspended(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_suspended(uid uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select p.suspended_until > now() from profiles p where p.id = uid), false);
$$;

--
-- Name: level_for_points(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.level_for_points(pts integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when pts >= 9500 then 10
    when pts >= 6000 then 9
    when pts >= 3800 then 8
    when pts >= 2400 then 7
    when pts >= 1500 then 6
    when pts >= 900  then 5
    when pts >= 500  then 4
    when pts >= 250  then 3
    when pts >= 100  then 2
    else 1
  end;
$$;

--
-- Name: local_ts(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.local_ts(at timestamp with time zone, tz integer) RETURNS timestamp without time zone
    LANGUAGE sql IMMUTABLE
    AS $$
  select (at at time zone 'UTC') + make_interval(mins => tz);
$$;

--
-- Name: mod_assert_admin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_assert_admin(p_statement text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_admin() then
    raise exception 'not authorised' using errcode = '42501';
  end if;
  if p_statement is not null and coalesce(trim(p_statement),'') = '' then
    raise exception 'a statement of reasons is required' using errcode = '22023';
  end if;
end $$;

--
-- Name: mod_delete_comment(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_delete_comment(p_comment uuid, p_reason text, p_statement text, p_report uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; ev jsonb;
begin
  perform mod_assert_admin(p_statement);
  select * into r from comments where id = p_comment;
  if r.id is null then raise exception 'no such comment'; end if;

  ev := jsonb_build_object('kind','comment', 'comment_id', r.id, 'user_id', r.user_id,
                           'post_id', r.post_id, 'body', r.body, 'created_at', r.created_at);
  perform mod_record('delete_comment', p_reason, p_statement, p_note, p_report, null, null, r.user_id, ev);

  perform set_config('crema.mod','ok',true);
  delete from comments where id = p_comment;
  perform set_config('crema.mod','',true);

  return null;
end $$;

--
-- Name: mod_delete_post(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mod_delete_post(p_post uuid, p_reason text, p_statement text, p_report uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; ev jsonb;
begin
  perform mod_assert_admin(p_statement);
  select * into r from posts where id = p_post;
  if r.id is null then raise exception 'no such pour'; end if;

  -- Everything that is about to stop existing. `image_key` above all:
  -- nothing else in this database will ever be able to tell you which
  -- object in R2 belonged to this row.
  ev := jsonb_build_object(
    'kind','post', 'post_id', r.id, 'user_id', r.user_id, 'drink', r.drink,
    'caption', r.caption, 'image_key', r.image_key, 'created_at', r.created_at,
    'r2_object_still_present', r.image_key is not null);

  -- Written before the delete, so the record survives the row.
  perform mod_record('delete_post', p_reason, p_statement, p_note, p_report, null, null, r.user_id, ev);

  perform set_config('crema.mod','ok',true);
  delete from posts where id = p_post;
  perform set_config('crema.mod','',true);

  return null;
end $$;

