--
-- Name: my_challenges(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_challenges() RETURNS TABLE(id text, cat text, kind text, goal integer, param text, title text, blurb text, tag text, pattern text, points integer, starts_at timestamp with time zone, ends_at timestamp with time zone, progress integer, done boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.cat, c.kind, c.goal, c.param, c.title, c.blurb,
         c.tag, c.pattern, c.points, c.starts_at, c.ends_at,
         challenge_progress(auth.uid(), c.id),
         exists (select 1 from challenge_completions cc
                  where cc.user_id = auth.uid() and cc.challenge_id = c.id)
    from challenges c
   where c.starts_at <= now() and c.ends_at > now() and c.kind is not null
   order by c.sort;
$$;

--
-- Name: notify_daily_champion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_daily_champion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into notifications (user_id, actor_id, type, post_id, body)
  values (new.user_id, null, 'daily_champion', new.post_id,
          'First coffee in Crema today · +' || new.points || ' points');
  return null;
exception when others then
  raise notice 'notify_daily_champion failed: %', sqlerrm;
  return null;
end $$;

--
-- Name: notify_on_comment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare owner uuid;
begin
  select user_id into owner from posts where id = new.post_id;
  if owner is null or owner = new.user_id then return new; end if;
  insert into notifications (user_id, actor_id, type, post_id, body)
  values (owner, new.user_id, 'commented on your pour', new.post_id, 'commented on your pour');
  return new;
end $$;

--
-- Name: notify_on_daily_first(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_daily_first() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.post_id is null then return null; end if;
  insert into notifications (user_id, actor_id, type, post_id, body)
  select f.follower_id, new.user_id, 'friend_pour', new.post_id, 'poured the first coffee of the day'
    from follows f
   where f.followee_id = new.user_id
     and f.status = 'accepted'
     and f.follower_id <> new.user_id            -- a self-follow is not news
     and not exists (select 1 from blocks b
                      where (b.blocker_id = f.follower_id and b.blocked_id = new.user_id)
                         or (b.blocker_id = new.user_id  and b.blocked_id = f.follower_id));
  return null;
exception when others then
  -- An inbox failure must never cost somebody the pour they just made.
  raise notice 'notify_on_daily_first failed: %', sqlerrm;
  return null;
end $$;

--
-- Name: notify_on_follow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_follow() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(current_setting('crema.reciprocal', true), '') = 'on' then
    return new;                       -- the follow-back; already announced
  end if;
  if new.status = 'accepted' then
    insert into notifications (user_id, actor_id, type, body)
    values (new.followee_id, new.follower_id, 'follow', 'started following you');
  else
    insert into notifications (user_id, actor_id, type, body)
    values (new.followee_id, new.follower_id, 'follow_request', 'wants to follow you');
  end if;
  return new;
end $$;

--
-- Name: notify_on_follow_accepted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_follow_accepted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.status is distinct from 'accepted' and new.status = 'accepted' then
    insert into notifications (user_id, actor_id, type, body)
    values (new.follower_id, new.followee_id, 'follow', 'accepted your follow request');
    -- the request itself is answered; it should stop sitting in the
    -- followee's inbox looking like something still to do
    delete from notifications
     where type = 'follow_request'
       and user_id = new.followee_id
       and actor_id = new.follower_id;
  end if;
  return new;
end $$;

--
-- Name: notify_on_follow_gone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_follow_gone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from notifications
   where type = 'follow_request'
     and user_id = old.followee_id
     and actor_id = old.follower_id;
  return old;
end $$;

--
-- Name: notify_on_like(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_like() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare owner uuid;
begin
  select user_id into owner from posts where id = new.post_id;
  if owner is null or owner = new.user_id then return new; end if;   -- no self-notify
  insert into notifications (user_id, actor_id, type, post_id, body)
  values (owner, new.user_id, 'like', new.post_id, 'liked your pour');
  return new;
end $$;

--
-- Name: notify_on_mention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_mention() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare owner uuid;
begin
  select user_id into owner from posts where id = new.post_id;
  insert into notifications (user_id, actor_id, type, post_id, body)
  select p.id, new.user_id, 'mention', new.post_id, 'mentioned you in a comment'
    from (select distinct lower(m[1]) as h
            from regexp_matches(coalesce(new.body,''), '@([A-Za-z0-9_.]+)', 'g') m
           limit 10) t
    join profiles p on lower(p.handle) = t.h
   where p.id <> new.user_id                 -- naming yourself is not news
     and p.id is distinct from owner;        -- they already got "commented on your pour"
  return new;
end $$;

--
-- Name: notify_on_reaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_reaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare owner uuid; phrase text;
begin
  select user_id into owner from posts where id = new.post_id;
  if owner is null or owner = new.user_id then return new; end if;   -- no self-notify
  phrase := case new.kind
    when 'art'   then 'loved your latte art'
    when 'scene' then 'loved where you had it'
    when 'drink' then 'loved your choice of coffee'
    else 'reacted to your pour' end;
  insert into notifications (user_id, actor_id, type, post_id, body)
  values (owner, new.user_id, 'reaction', new.post_id, phrase);
  return new;
end $$;

--
-- Name: podium_award_day(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.podium_award_day(d date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if d >= podium_day() then return; end if;
  if exists (select 1 from podium_wins where day = d) then return; end if;

  insert into podium_wins (day, post_id, user_id, place, points)
  select d, t.post_id, t.user_id, t.place,
         case t.place when 1 then 15 when 2 then 10 else 5 end
    from podium_top(d) t;

  perform recalc_score(user_id) from podium_wins where day = d;
end $$;

--
-- Name: podium_award_recent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.podium_award_recent() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d date;
begin
  for d in select generate_series(podium_day() - 7, podium_day() - 1, interval '1 day')::date
  loop
    perform podium_award_day(d);
  end loop;
end $$;

--
-- Name: podium_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.podium_check() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  d date := podium_day();
  r record;
  medal text; ord text;
begin
  -- Anyone knocked off loses their bookmark, so climbing back announces
  -- itself again.
  delete from podium_places pp
   where pp.day = d
     and not exists (select 1 from podium_top(d) t where t.post_id = pp.post_id);

  -- Yesterday's podium is settled and nothing will re-announce it. Keep a
  -- week for debugging, then let it go.
  delete from podium_places where day < d - 7;

  for r in select * from podium_top(d) loop
    -- The WHERE on the conflict path is what makes this idempotent: an
    -- unchanged place updates nothing, leaves FOUND false, and stays
    -- quiet.
    insert into podium_places (day, post_id, user_id, place)
    values (d, r.post_id, r.user_id, r.place)
    on conflict (day, post_id) do update
       set place = excluded.place, updated_at = now()
     where podium_places.place is distinct from excluded.place;

    if found then
      medal := case r.place when 1 then '🥇' when 2 then '🥈' else '🥉' end;
      ord   := case r.place when 1 then '1st' when 2 then '2nd' else '3rd' end;
      insert into notifications (user_id, actor_id, type, post_id, body)
      values (r.user_id, null, 'podium', r.post_id,
              medal || ' ' || ord || ' place on today''s podium');
    end if;
  end loop;
end $$;

--
-- Name: podium_day(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.podium_day() RETURNS date
    LANGUAGE sql STABLE
    AS $$
  select (now() at time zone 'Europe/Berlin')::date;
$$;

--
-- Name: podium_top(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.podium_top(d date DEFAULT NULL::date) RETURNS TABLE(post_id uuid, user_id uuid, place integer, likes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with day_posts as (
    select p.id, p.user_id, p.created_at,
           (select count(*) from likes l where l.post_id = p.id) as likes,
           (select count(*) from comments c
             where c.post_id = p.id and c.user_id is distinct from p.user_id) as comments
      from posts p
     where p.visibility = 'public'
       and p.hidden_at is null
       and (p.created_at at time zone 'Europe/Berlin')::date = coalesce(d, podium_day())
  )
  select id, user_id,
         (row_number() over (order by likes + comments desc, created_at asc))::int,
         likes
    from day_posts
   where likes + comments > 0
   order by likes + comments desc, created_at asc
   limit 3;
$$;

--
-- Name: posts_guard_edit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posts_guard_edit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Moderation is not an edit.
  if coalesce(current_setting('crema.mod', true),'') = 'ok' then
    return new;
  end if;

  -- Maintenance is not an edit either. migrate-base64-images.mjs rewrites
  -- image_key on purpose, with the service key, and the SQL editor runs
  -- as the owner — this guard exists to bound what end users can do, not
  -- to fence off the operator.
  -- PostgREST always connects as `authenticator` and then switches role;
  -- anything else (SQL editor, psql, a cron job) isn't an API request.
  if session_user <> 'authenticator'
     or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role' then
    return new;
  end if;

  -- Ownership and identity: an update never re-homes a post.
  if new.user_id is distinct from old.user_id then
    raise exception 'a post cannot change author';
  end if;
  if new.id is distinct from old.id then
    raise exception 'a post cannot change id';
  end if;

  -- The photo is the evidence; the text around it is the claim. Swapping
  -- the image after people have liked it would make likes meaningless.
  if new.image_key is distinct from old.image_key then
    raise exception 'a post''s photo cannot be changed';
  end if;

  -- created_at is what the edit window is measured against, so it is the
  -- one field an attacker would want to move first.
  if new.created_at is distinct from old.created_at then
    raise exception 'a post cannot change its timestamp';
  end if;

  -- Moderation state belongs to the moderator. Without this the author
  -- could PATCH hidden_at back to null and put the pour straight back on
  -- the feed — their own update policy would allow it.
  if new.hidden_at is distinct from old.hidden_at
     or new.hidden_by is distinct from old.hidden_by then
    raise exception 'moderation state cannot be changed here';
  end if;

  -- The edit window. The client's rule is the user's local calendar day;
  -- the database can't know that timezone, so it enforces a slightly
  -- wider backstop instead of second-guessing it. Anything the client
  -- legitimately allows falls inside 36 hours; anything a week old does
  -- not. The narrow rule is the UI's, this is the ceiling.
  if old.created_at < now() - interval '36 hours' then
    raise exception 'a post can only be edited on the day it was posted';
  end if;

  -- Stamped here, never by the client: a marker the author can set is a
  -- marker the author can clear.
  new.edited_at := now();
  return new;
end;
$$;

--
-- Name: premium_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.premium_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.premium and not coalesce(old.premium, false)
     and coalesce(current_setting('crema.redeem', true), '') <> 'ok' then
    new.premium := old.premium;
  end if;
  return new;
end $$;

--
-- Name: profiles_guard_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profiles_guard_admin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if session_user <> 'authenticator'
     or coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role','') = 'service_role'
     or coalesce(current_setting('crema.mod', true),'') = 'ok' then
    return new;
  end if;
  -- Silently reverted rather than raised: "Save profile" sends the whole
  -- row, and an ordinary save must not fail because it echoed back a
  -- column it never meant to touch. Same reasoning as premium_guard.
  new.is_admin        := old.is_admin;
  new.suspended_until := old.suspended_until;
  new.suspended_reason:= old.suspended_reason;
  return new;
end $$;

--
-- Name: push_config(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_config(k text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v text;
begin
  begin
    select decrypted_secret into v
      from vault.decrypted_secrets where name = k limit 1;
    if v is not null and v <> '' then return v; end if;
  exception when others then
    -- No vault extension, or no permission: fall through to the GUC.
    null;
  end;
  return nullif(current_setting('app.' || k, true), '');
end $$;

--
-- Name: push_morning_nudge(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_morning_nudge() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rows jsonb; n int;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into rows from (
    select jsonb_build_object(
             'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth,
             'title', case when r.n > 0 then 'Keep the streak going' else 'Good morning ☕' end,
             'body',  case when r.n > 0
                           then r.n || ' days so far — log today''s and make it ' || (r.n + 1) || '.'
                           else 'Log today''s coffee before it''s just a memory.' end,
             'url',   './',
             'tag',   'morning'
           ) as x
      from push_subscriptions s
      join profiles p on p.id = s.user_id and p.notify_morning
      -- Whether this device's user has already poured today, in their
      -- own timezone. Computed here rather than reused from
      -- streak_at_risk() because that function answers 0 for two
      -- different reasons — "poured today" and "no streak at all" — and
      -- this nudge has to tell them apart to skip the first and still
      -- reach the second.
      cross join lateral (
        select exists (
                 select 1 from posts po
                  where po.user_id = s.user_id
                    and (po.created_at + make_interval(mins => s.tz_offset))::date
                        = (now() + make_interval(mins => s.tz_offset))::date
               ) as poured_today
      ) t
      cross join lateral (select streak_at_risk(s.user_id, s.tz_offset) as n) r
     where not t.poured_today
       and extract(hour from (now() + make_interval(mins => s.tz_offset))) = 8
  ) q;

  n := jsonb_array_length(rows);
  if n > 0 then perform push_send(jsonb_build_object('rows', rows)); end if;
  raise notice 'morning nudges: % device(s)', n;
end $$;

--
-- Name: push_on_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_on_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor text; rows jsonb;
begin
  if not exists (select 1 from profiles where id = new.user_id and notify_social) then
    return new;
  end if;

  select coalesce(nullif(name,''), '@' || handle) into actor
    from profiles where id = new.actor_id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth,
           -- The app is called Crema in both languages.
           'title', 'Crema',
           'body',  coalesce(actor || ' ', '')
                    || crema_push_body(coalesce(new.body, new.type), s.lang),
           'url',   case when new.post_id is not null then './#p/' || new.post_id else './' end,
           'tag',   new.type || ':' || coalesce(new.actor_id::text,'-')
         )), '[]'::jsonb)
    into rows
    from push_subscriptions s
   where s.user_id = new.user_id;

  perform push_send(jsonb_build_object('rows', rows));
  return new;
exception when others then
  raise notice 'push_on_notification failed: %', sqlerrm;
  return new;
end $$;

--
-- Name: push_send(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_send(payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare url text; secret text;
begin
  url    := push_config('push_endpoint');
  secret := push_config('push_secret');
  if url is null or url = '' then
    raise notice 'push_endpoint unset — skipping push (see supabase/README.md §5)';
    return;
  end if;
  if jsonb_array_length(coalesce(payload->'rows','[]'::jsonb)) = 0 then return; end if;
  perform net.http_post(
    url     := url,
    headers := jsonb_build_object('Content-Type','application/json','X-Push-Secret',coalesce(secret,'')),
    body    := payload
  );
end $$;

--
-- Name: push_set_config(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_set_config(k text, v text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare sid uuid;
begin
  select id into sid from vault.secrets where name = k;
  if sid is null then perform vault.create_secret(v, k, 'Crema push configuration');
  else                perform vault.update_secret(sid, v);
  end if;
end $$;

--
-- Name: push_streak_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_streak_reminders() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rows jsonb; n int;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into rows from (
    select jsonb_build_object(
             'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth,
             'title', crema_i18n('Your streak ends tonight', s.lang),
             'body',  replace(crema_i18n('{n} days so far — one pour keeps it going.', s.lang),
                              '{n}', d.n::text),
             'url',   './',
             'tag',   'streak'
           ) as x
      from push_subscriptions s
      join profiles p on p.id = s.user_id and p.notify_streak
      cross join lateral (select streak_at_risk(s.user_id, s.tz_offset) as n) d
     where d.n > 0
       and extract(hour from (now() + make_interval(mins => s.tz_offset))) = 19
  ) q;

  n := jsonb_array_length(rows);
  if n > 0 then perform push_send(jsonb_build_object('rows', rows)); end if;
  raise notice 'streak reminders: % device(s)', n;
end $$;

--
-- Name: push_weekly_digest(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_weekly_digest() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rows jsonb; n int;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into rows from (
    select jsonb_build_object(
             'endpoint', s.endpoint, 'p256dh', s.p256dh, 'auth', s.auth,
             'title', crema_i18n('Your week in coffee', s.lang),
             'body',  crema_digest_body(w.pours, w.likes, w.followers, s.lang),
             'url',   './',
             'tag',   'digest'
           ) as x
      from push_subscriptions s
      join profiles p on p.id = s.user_id and p.notify_digest
      cross join lateral (
        select
          (select count(*) from posts po
            where po.user_id = s.user_id and po.created_at > now() - interval '7 days') as pours,
          (select count(*) from likes l join posts po on po.id = l.post_id
            where po.user_id = s.user_id and l.created_at > now() - interval '7 days') as likes,
          (select count(*) from follows f
            where f.followee_id = s.user_id and f.status = 'accepted'
              and f.created_at > now() - interval '7 days') as followers
      ) w
     where (w.pours > 0 or w.likes > 0 or w.followers > 0)
       and extract(dow  from (now() + make_interval(mins => s.tz_offset))) = 1
       and extract(hour from (now() + make_interval(mins => s.tz_offset))) = 8
  ) q;

  n := jsonb_array_length(rows);
  if n > 0 then perform push_send(jsonb_build_object('rows', rows)); end if;
  raise notice 'weekly digest: % device(s)', n;
end $$;

--
-- Name: recalc_score(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalc_score(uid uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare pts int;
begin
  if uid is null then return; end if;
  pts := user_points(uid);
  update profiles
     set points = pts,
         level  = level_for_points(pts)
   where id = uid
     and (points is distinct from pts or level is distinct from level_for_points(pts));
end $$;

--
-- Name: redeem_premium(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_premium(code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare want constant text := 'FIRSTPOUR';
begin
  if auth.uid() is null then return false; end if;
  if upper(regexp_replace(coalesce(code, ''), '[^a-zA-Z0-9]', '', 'g')) <> want then
    return false;
  end if;

  perform set_config('crema.redeem', 'ok', true);
  update profiles
     set premium    = true,
         premium_at = coalesce(premium_at, now())
   where id = auth.uid();
  perform set_config('crema.redeem', '', true);

  return true;
end $$;

--
-- Name: report_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  url text; secret text;
  target text; target_id uuid;
  author_id uuid; author_handle text; excerpt text; link text;
  reporter_handle text;
begin
  url    := push_config('report_endpoint');
  secret := push_config('push_secret');
  if url is null or url = '' then
    raise notice 'report_endpoint unset — report % filed but not emailed (see supabase/README.md §6)', new.id;
    return new;
  end if;
  if secret is null or secret = '' then
    raise notice 'push_secret unset — report % filed but not emailed (see supabase/README.md §6)', new.id;
    return new;
  end if;

  -- Exactly one of the three is non-null; the table's one_target check
  -- constraint (step-1.7) is what makes this an if/elsif rather than a
  -- set of independent lookups.
  if new.post_id is not null then
    target := 'post'; target_id := new.post_id;
    select p.user_id, left(coalesce(p.caption,''), 180)
      into author_id, excerpt
      from posts p where p.id = new.post_id;
    -- The app understands #p/<id> and opens the pour on it, which is a
    -- faster route to a decision than any admin screen we don't have.
    link := 'https://crema-app.com/#p/' || new.post_id;
  elsif new.comment_id is not null then
    target := 'comment'; target_id := new.comment_id;
    select c.user_id, left(coalesce(c.body,''), 180), 'https://crema-app.com/#p/' || c.post_id
      into author_id, excerpt, link
      from comments c where c.id = new.comment_id;
  else
    target := 'user'; target_id := new.user_id; author_id := new.user_id;
  end if;

  select nullif(handle,'') into author_handle   from profiles where id = author_id;
  select nullif(handle,'') into reporter_handle from profiles where id = new.reporter_id;

  perform net.http_post(
    url     := url,
    headers := jsonb_build_object('Content-Type','application/json','X-Push-Secret',secret),
    body    := jsonb_build_object('report', jsonb_build_object(
      'id',              new.id,
      'reason',          new.reason,
      'note',            new.note,
      'created_at',      coalesce(new.created_at, now()),
      'target',          target,
      'target_id',       target_id,
      'reporter_id',     new.reporter_id,
      'reporter_handle', reporter_handle,
      'author_id',       author_id,
      'author_handle',   author_handle,
      'excerpt',         nullif(excerpt,''),
      'link',            link
    ))
  );
  return new;
exception when others then
  -- Filing must never fail because the mailer did. Someone reporting
  -- abuse gets "Reported. Thanks" either way, and the row — the thing
  -- moderation actually runs on — is already written.
  raise notice 'report_notify failed for %: %', new.id, sqlerrm;
  return new;
end $$;

--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;

--
-- Name: streak_at_risk(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.streak_at_risk(uid uuid, tz_min integer) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  today date := local_ts(now(), tz_min)::date;
  days  int[];                      -- day indices: 0 = today, 1 = yesterday
  r     record;
  total int;
begin
  select coalesce(array_agg(distinct (today - local_ts(p.created_at, tz_min)::date)), '{}')
    into days
    from posts p
   where p.user_id = uid
     and p.created_at > now() - interval '400 days'
     and local_ts(p.created_at, tz_min)::date <= today;

  -- Poured today already, or never poured: nothing is at risk.
  if 0 = any(days) or array_length(days, 1) is null then return 0; end if;

  if 1 = any(days) then
    -- The ordinary case: a live run ending yesterday, today still open.
    select * into r from streak_run(days, 1);
    total := r.n;
  else
    -- Nothing yesterday either. The streak survives only if it earned a
    -- rest day and is spending it on yesterday — so the run behind it
    -- must reach the threshold AND must not have needed a rest of its
    -- own, since the allowance is one per streak, not one per gap.
    select * into r from streak_run(days, 2);
    if r.n >= crema_rest_after() and not r.rested then total := r.n; else return 0; end if;
  end if;

  -- Only report a streak worth defending. A single day is not yet a
  -- habit, and "your 1-day streak ends tonight" is a notification nobody
  -- keeps enabled.
  if total < 2 then return 0; end if;
  return total;
end $$;

--
-- Name: streak_run(integer[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.streak_run(days integer[], start integer, OUT n integer, OUT rested boolean) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare d int; fwd int; ra int := crema_rest_after();
begin
  n := 0; rested := false; d := start;
  loop
    if d = any(days) then
      n := n + 1; d := d + 1;
    elsif not rested and (d + 1) = any(days) then
      -- Plain (non-forgiving) run on the older side, matching the
      -- deliberate use of plainRun() in the JS: a recursive check would
      -- let each forgiven gap earn the next one, and pouring every other
      -- day forever would read as an unbroken streak.
      fwd := 0;
      while (d + 1 + fwd) = any(days) loop fwd := fwd + 1; end loop;
      exit when n < ra and fwd < ra;
      rested := true; d := d + 1;   -- crosses the gap; the missed day itself isn't counted
    else
      exit;
    end if;
  end loop;
end $$;

