--
-- Name: user_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_points(uid uuid) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select
      -- a coffee logged
      coalesce((select count(*) from posts where user_id = uid), 0) * 10

      -- likes other people put on your pours
    + coalesce((select count(*) from likes l
                  join posts p on p.id = l.post_id
                 where p.user_id = uid), 0) * 2

      -- comments other people left on your pours (never your own)
    + coalesce((select count(*) from comments c
                  join posts p on p.id = c.post_id
                 where p.user_id = uid
                   and c.user_id is distinct from p.user_id), 0) * 3

      -- pours you logged with a repeatable recipe: dose in, yield out
    + coalesce((select count(*) from posts
                 where user_id = uid
                   and coalesce(btrim(recipe->>'dose'),  '') <> ''
                   and coalesce(btrim(recipe->>'yield'), '') <> ''), 0) * 5

      -- distinct beans you have logged, counted once each
    + coalesce((select count(distinct lower(btrim(recipe->>'bean'))) from posts
                 where user_id = uid
                   and coalesce(btrim(recipe->>'bean'), '') <> ''), 0) * 15

      -- challenges finished, each worth what it said it was worth
    + coalesce((select sum(points) from challenge_completions
                 where user_id = uid), 0)

      -- days finished on the podium, each worth what podium_award_day()
      -- gave it (15 / 10 / 5 for 1st / 2nd / 3rd)
    + coalesce((select sum(points) from podium_wins
                 where user_id = uid), 0)

      -- mornings you were first in all of Crema
    + coalesce((select sum(points) from daily_champions
                 where user_id = uid), 0);
$$;

--
-- Name: user_tz(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_tz(uid uuid) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  select coalesce((select tz_offset from profiles where id = uid), 0);
$$;

--
-- Name: week_standing(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.week_standing(from_ts timestamp with time zone, to_ts timestamp with time zone) RETURNS TABLE(drinkers integer, pours integer, ahead_pct integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with tallies as (
    select user_id, count(*)::int as n
      from posts
     where created_at >= from_ts and created_at < to_ts
     group by user_id
  ),
  me as (
    select coalesce((select n from tallies where user_id = auth.uid()), 0) as n,
           (select count(*)::int from tallies) as total
  )
  select
    me.total,
    me.n,
    case when me.total > 1 and me.n > 0 and auth.uid() is not null
         then round(100.0 * (select count(*) from tallies where n < me.n)
                          / (me.total - 1))::int
         else null end
  from me;
$$;

