--
-- Name: podium_today; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.podium_today WITH (security_invoker='true') AS
 SELECT p.id,
    p.user_id,
    p.drink,
    p.art,
    p.pattern,
    p.quality,
    p.image_key,
    p.caption,
    p.cafe_id,
    p.recipe,
    p.created_at,
    pr.handle,
    pr.name,
    pr.city,
    pr.avatar_color,
    pr.level,
    t.likes AS like_count,
    t.place,
    ( SELECT count(*) AS count
           FROM public.comments c
          WHERE (c.post_id = p.id)) AS comment_count
   FROM ((public.podium_top() t(post_id, user_id, place, likes)
     JOIN public.posts p ON ((p.id = t.post_id)))
     JOIN public.profiles pr ON ((pr.id = p.user_id)));

