);

--
-- Name: post_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.post_counts WITH (security_invoker='true') AS
 SELECT id AS post_id,
    ( SELECT count(*) AS count
           FROM public.likes l
          WHERE (l.post_id = p.id)) AS like_count,
    ( SELECT count(*) AS count
           FROM public.comments c
          WHERE (c.post_id = p.id)) AS comment_count
   FROM public.posts p;

--
-- Name: profile_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.profile_counts WITH (security_invoker='true') AS
 SELECT id AS profile_id,
    ( SELECT count(*) AS count
           FROM public.follows f
          WHERE ((f.followee_id = pr.id) AND (f.status = 'accepted'::text))) AS follower_count,
    ( SELECT count(*) AS count
           FROM public.follows f
          WHERE ((f.follower_id = pr.id) AND (f.status = 'accepted'::text))) AS following_count,
    ( SELECT count(*) AS count
           FROM public.posts p
          WHERE (p.user_id = pr.id)) AS pour_count
   FROM public.profiles pr;

